"""Golden tests for data/test_cases (generated by scripts/generate_test_cases.py).

Cases run in manifest order against a fresh ledger because duplicates and
number collisions depend on what came before. Outcomes use the offline mock
provider; approver_called marks the judgment cases a real model should be
evaluated on separately.
"""

import json

import pytest

from invoice_ap.config import DATA_DIR
from invoice_ap.mock_llm import MockProvider
from invoice_ap.pipeline import process_file

CASE_DIR = DATA_DIR / "test_cases"
CASES = json.loads((CASE_DIR / "expected.json").read_text())["cases"]


@pytest.fixture(scope="module")
def results():
    from invoice_ap.db import init_db

    conn = init_db(":memory:")
    provider = MockProvider()
    return {c["file"]: process_file(CASE_DIR / c["file"], conn, provider, run_id="tc")
            for c in CASES}


@pytest.mark.parametrize("case", CASES, ids=[c["file"] for c in CASES])
def test_case(case, results):
    r = results[case["file"]]
    codes = {x["code"] for x in r.reasons}
    assert r.outcome.value == case["outcome"], (case["why"], r.path)
    assert set(case["must_include"]) <= codes, (case["why"], codes)
    assert (r.approval is not None) == case["approver_called"], case["why"]


def test_every_case_file_is_in_the_manifest():
    files = {p.name for p in CASE_DIR.iterdir()} - {"expected.json"}
    assert files == {c["file"] for c in CASES}


def test_the_approver_is_exercised_by_the_extra_cases():
    assert sum(c["approver_called"] for c in CASES) >= 6


def test_injection_never_reaches_a_model(results):
    r = results["tc08_prompt_injection.json"]
    assert r.approval is None and not [u for u in r.usage if u.role == "approver"]
